class Solution {
public:
    int arithmeticTriplets(vector<int>& nums, int diff) {
        int n = nums.size();
        int count = 0;
        int i = 0, k = 0;
        for (int j = 0; j < n; j++) {
            while (i < j && nums[j] - nums[i] > diff) i++;
            while (k < n - 1 && nums[k] - nums[j] < diff) k++;
            if (i < j && nums[j] - nums[i] == diff && k > j && nums[k] - nums[j] == diff) {
                count++;
            }
        }
        return count;
    }
};
